#include <iostream>

bool crear(int*& actual, int valor) {
    if (actual != nullptr || valor < 0 || valor > 9) {
        return false;
    }
    // Crea el entero y deja su acceso en actual.
    return false;
}

bool retirar(int*& actual) {
    if (actual == nullptr) {
        return false;
    }
    // Libera el entero, deja actual nulo y comunica lo realizado.
    return false;
}

int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) {
        return 1;
    }
    int* actual = nullptr;
    bool hayCopia = false;
    int copia = 0;
    int creados = 0;
    int liberados = 0;

    for (int i = 0; i < ordenes; ++i) {
        int operacion = 0;
        int valor = 0;

        if (!(std::cin >> operacion >> valor)) {
            retirar(actual);
            return 1;
        }
        const char* estado = "Orden";
        if (operacion == 1) {
            if (crear(actual, valor)) {
                ++creados;
                estado = "Creado";
            } else {
                estado = "Rechazo";
            }
        } else if (operacion == 2) {
            if (actual != nullptr && valor >= 0 && valor <= 9) {
                *actual = valor;
                estado = "Cambio";
            } else {
                estado = "Rechazo";
            }
        } else if (operacion == 3) {
            if (retirar(actual)) {
                ++liberados;
                estado = "Liberado";
            } else {
                estado = "Vacio";
            }
        } else if (operacion == 4) {
            if (actual != nullptr) {
                copia = *actual;
                hayCopia = true;
                estado = "Copia";
            } else {
                estado = "Rechazo";
            }
        }
        std::cout << "Estado:" << estado << ";Actual:";
        if (actual == nullptr) {
            std::cout << 'X';
        } else {
            std::cout << *actual;
        }
        std::cout << ";Copia:";
        if (hayCopia) {
            std::cout << copia;
        } else {
            std::cout << 'X';
        }
        std::cout << ";Creados:" << creados << ";Liberados:" << liberados << '\n';
    }
    const bool cierre = retirar(actual);
    if (cierre) {
        ++liberados;
    }
    std::cout << "Cierre:" << cierre << ";Creados:" << creados
              << ";Liberados:" << liberados << '\n';
    return 0;
}

